/** deep-merge saved settings over defaults (types merged per id, so new types appear after updates) */
function mergeSettings(saved) {
  const s = Object.assign(clone(DEFAULT_SETTINGS), saved || {});
  s.novel = Object.assign(clone(DEFAULT_SETTINGS.novel), (saved && saved.novel) || {});
  s.plotweaver = Object.assign(clone(DEFAULT_SETTINGS.plotweaver), (saved && saved.plotweaver) || {});
  s.maps = mergeMapSettings(saved && saved.maps);
  const types = clone(DEFAULT_TYPES);
  for (const [id, t] of Object.entries((saved && saved.types) || {})) types[id] = Object.assign(types[id] || {}, t);
  // occupation is plain text on the character sheet (not a link): move it out of saved link fields
  const ch = types.character;
  if (ch) {
    if (Array.isArray(ch.links)) ch.links = ch.links.filter((l) => l.key !== 'occupation');
    if (Array.isArray(ch.text) && !ch.text.some((x) => x.key === 'occupation')) ch.text = [...ch.text, { key: 'occupation', label: 'Occupation', tile: true }];
  }
  s.types = types;
  return s;
}

/* ---- worldkeeper/10-store.js ---- */
/* =====================================================================
   store: read frontmatter through Obsidian's metadata cache, write through
   processFrontMatter, and keep an index of types / hierarchy / backlinks.
   ===================================================================== */
/** wait for Obsidian to re-read a note's metadata (or give up after a moment) */
function afterMeta(f, ms = 1500) {
  return new Promise((res) => { const mc = app().metadataCache; let t = null; const ref = mc.on('changed', (x) => { if (x && x.path === f.path) { mc.offref(ref); clearTimeout(t); setTimeout(res, 0); } }); t = setTimeout(() => { mc.offref(ref); res(); }, ms); });
}
/** the editor showing this note in Source / Live Preview, if any */
function openEditorFor(f) {
  let view = null;
  app().workspace.iterateAllLeaves((l) => { const v = l.view; if (!view && v && v.file && v.file.path === f.path && v.editor && typeof v.getMode === 'function' && v.getMode() === 'source') view = v; });
  return view;
}
/** current text of a note, from its open editor when there is one (the editor may be ahead of the file on disk) */
