  const list = h('div', { class: 'wkm-sg-list' }); const inp = h('input', { type: 'text', placeholder, class: 'wkm-sg-input' });
  const box = h('div', { class: 'wkm-suggest' }, title ? h('div', { class: 'wkm-sg-title' }, title) : null, inp, list);
