    if (create && q && !items.some((o) => o.label.toLowerCase() === q)) shown.push({ label: `Create “${inp.value.trim()}”`, icon: '＋', value: inp.value.trim(), create: true });
    active = clamp(active, 0, Math.max(0, shown.length - 1));
