        if (arr(it.chars).length) { y += 2; para(L + 18, 'Travellers: ' + arr(it.chars).map(mDisplay).join(', '), 8.5); y -= 2; }
        if (it.desc) { y += 2; para(L + 18, it.desc, 8.5); y -= 2; }
