  const all = (SG.data.draftPlots ??= {});
  const s = (all[novelId] ??= { active: '', plots: [] });
  if (!s.plots.length) s.plots.push(newDraftPlot('Draft plot 1'));
  if (!s.plots.some((p) => p.id === s.active)) s.active = s.plots[0].id;
