  const K = DSS().keys; const sk = statusKey();
  const tbl = el('table', { class: 'ds-table ds-chtable' }, el('thead', {}, el('tr', {}, ['', '#', 'Chapter', 'Type', 'Draft', 'Status', 'Words', 'POV', 'Plot Weaver', ''].map((x) => el('th', {}, x)))));
  let dragFrom = null;
