    const by = [0, 0, 0, 0, 0, 0, 0], cnt = [0, 0, 0, 0, 0, 0, 0]; r.filter((d) => !d.empty).forEach((d) => { by[d.d.getDay()] += Math.max(0, d.words); cnt[d.d.getDay()]++; });
